    if isinstance(n, int):
        return str(n)
    s = infix(n.l, PREC[n.op]) + " " + n.op + " " + infix(n.r, PREC[n.op])
    return "(" + s + ")" if PREC[n.op] < parent_prec else s
def postfix(n, out):
    if isinstance(n, int):
        out.append(str(n))
        return
    postfix(n.l, out)
    postfix(n.r, out)
    out.append(n.op)
