def find_path(src, dst):
    parent = {src: None}
    q = deque([src])
    while q:
        u = q.popleft()
        if u == dst:
            break
        for w in adj.get(u, []):
            if w not in parent:
                parent[w] = u
                q.append(w)
    if dst not in parent:
        return None
    path = []
    n = dst
    while n is not None:
        path.append(n)
        n = parent[n]
    return list(reversed(path))
