def is_tree(nodes, edges):
    if len(edges) != len(nodes) - 1:
        return False, f"edges = {len(edges)}, nodes - 1 = {len(nodes) - 1}"
    adj = {n: [] for n in nodes}
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    seen = set()
    stack = [next(iter(nodes))]
    while stack:
        u = stack.pop()
        if u in seen:
            continue
        seen.add(u)
        stack.extend(adj[u])
    if seen != set(nodes):
        return False, f"only {len(seen)} of {len(nodes)} nodes reachable"
    return True, "edges = nodes - 1 and connected"
