import heapq
hops = {"S": ["A", "B"], "A": ["S", "T"], "B": ["S", "T"], "T": ["A", "B"]}
def bfs_hops(src):
    dist = {src: 0}
    q = deque([src])
    while q:
        u = q.popleft()
        for w in hops[u]:
            if w not in dist:
                dist[w] = dist[u] + 1
                q.append(w)
    return dist["T"]
times = {"S": [("A", 50), ("B", 10)], "A": [("S", 50), ("T", 50)],
         "B": [("S", 10), ("T", 10)], "T": [("A", 50), ("B", 10)]}
def dijkstra(src):
    dist = {src: 0}
    pq = [(0, src)]
    done = set()
    while pq:
        d, u = heapq.heappop(pq)
        if u in done:
            continue
        done.add(u)
        for v, w in times[u]:
            nd = d + w
            if nd < dist.get(v, float("inf")):
                dist[v] = nd
                heapq.heappush(pq, (nd, v))
    return dist["T"]
print("fewest hops S -> T:", bfs_hops("S"), "(both routes tie)")
print("fastest S -> T:", dijkstra("S"), "minutes (via B)")

